#include <stdio.h>

typedef enum {
    MISCONCEPTION_NONE,
    MISCONCEPTION_POSTFIX_VALUE,
    MISCONCEPTION_ARRAY_BOUND
} Misconception;

typedef struct {
    int correct;
    Misconception misconception;
} Response;

static const char *feedback_for(Response response) {
    if (response.correct) {
        return "Correct: explain the rule in your own words.";
    }

    switch (response.misconception) {
        case MISCONCEPTION_POSTFIX_VALUE:
            return "Trace the old value and the stored value separately.";
        case MISCONCEPTION_ARRAY_BOUND:
            return "Check valid indices: zero through count minus one.";
        case MISCONCEPTION_NONE:
        default:
            return "Review the question contract, then try a fresh example.";
    }
}

int main(void) {
    const Response responses[] = {
        {0, MISCONCEPTION_POSTFIX_VALUE},
        {0, MISCONCEPTION_ARRAY_BOUND},
        {1, MISCONCEPTION_NONE}
    };
    const size_t count = sizeof responses / sizeof responses[0];

    for (size_t i = 0; i < count; ++i) {
        printf("%s\n", feedback_for(responses[i]));
    }
    return 0;
}
